import json, random, sys, time
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/vendor'); sys.path.insert(0,'/workspace/submission')
import verify, controller

def wide_case(J=512,S=256,F=32,G=32,q=512,B=512,I=512,seed=1):
    rng=random.Random(seed)
    times=[i*(10**9//max(1,S-1)) for i in range(S)]
    slots=[[times[i], q, 0 if i==0 else 0] for i in range(S)]
    groups=[]
    for g in range(G):
        p = -1 if g < F else rng.choice([-1]+[x for x in range(g) if x>=0])
        groups.append([p if p is not None else -1, 512])
    flows=[]
    for f in range(F):
        tg=rng.randint(1,8)
        flows.append([tg, max(tg,rng.randint(1,40)), rng.randint(0,G-1) if G else -1, rng.randint(0,6)])
    windows=[]
    for j in range(J):
        windows.append([j%F, 0, times[-1], rng.randint(1,65535), rng.randint(1,320),
                        rng.randint(0,70000), rng.randint(1,1000),
                        [[rng.randint(0,1500),rng.randint(0,2560)] for _ in range(9)]])
    return {'model':rng.choice(['cnn','rnn']),'class_values':[rng.randint(1,1000) for _ in range(7)],
            'stats':[rng.randint(1,300)]*3,'bucket':[B,I],'slots':slots,'flows':flows,'groups':groups,'windows':windows}

def run(c, check=True, label=''):
    req={'version':3,'cases':[c]}
    t=time.time(); resp=controller.run(json.dumps(req).encode()); dt=time.time()-t
    line='%s time %.2fs' % (label, dt)
    if check:
        try:
            verify.check_request(req,resp)
            line += ' verified ok  ratio=%s U=%s A=%s nsel=%d arcs=%d' % (resp['results'][0]['ratio'], resp['results'][0]['utility'], resp['results'][0]['age'], sum(1 for a in resp['results'][0]['assignment'] if a>=0), len(resp['results'][0]['flow']))
        except Exception as e:
            line += ' FAIL '+type(e).__name__+' '+str(e)[:120]
    print(line, flush=True)

if __name__=='__main__':
    which = sys.argv[1] if len(sys.argv)>1 else 'wide'
    if which=='wide':
        run(wide_case(), label='wide-512x256')
    elif which=='narrow':
        run(wide_case(S=256,q=2,B=4,I=2), label='tokens-tight')
    elif which=='manyslots':
        run(wide_case(J=64,S=256,q=1,B=1,I=1), label='one-per-slot')
    elif which=='max':
        run(wide_case(J=512,S=256,F=32,G=32,q=2,B=3,I=1), label='max-adversarial')
PYEOF
